glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv;
out vec4 tint;
vec4 vert () {
  vec4 p=vec4(a_position,1.);
  #if USE_LOCAL
    p=cc_matWorld*p;
  #endif
  uv=a_texCoord; tint=a_color;
  return cc_matViewProj*p;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
uniform sampler2D cc_spriteTexture;
uniform sampler2D surfaceMap;
layout(std140) uniform JadeLighting { vec4 pose; };
in vec2 uv;
in vec4 tint;
vec2 onSlice(vec2 p) {
  return clamp(p,vec2(.0017,pose.z/3.+.0016),vec2(.9983,(pose.z+1.)/3.-.0016));
}
vec4 beauty(vec2 p) {
  return CCSampleWithAlphaSeparated(cc_spriteTexture,onSlice(p));
}
float softbox(vec2 p, vec2 widths) {
  vec2 q=vec2(dot(p,vec2(.89,.456)),dot(p,vec2(-.456,.89)))/widths;
  return exp(-dot(q,q));
}
float reflection(vec3 n, vec3 eye, float faceted) {
  vec3 ray=reflect(-eye,n);
  vec2 key=ray.xy/max(.53,ray.z)-vec2(-.38,.44);
  float wide=softbox(key,vec2(mix(.51,.27,faceted),.85));
  float narrow=softbox(key+vec2(.03,.02),vec2(mix(.14,.075,faceted),mix(.43,.62,faceted)));
  return .11*wide+.20*narrow;
}
vec4 frag () {
  vec2 unit=vec2(1./50.,1./54.);
  vec2 lean=vec2(pose.x,-pose.y);
  vec2 lift=unit*(vec2(-.22,-.42)+lean*1.28);
  vec4 reliefSample=texture(surfaceMap,onSlice(uv-lift*.8));
  float height=clamp((reliefSample.b*255.-216.)/36.,0.,1.);
  vec2 topUV=onSlice(uv-lift*(.76+.39*height));
  vec4 cap=beauty(topUV);
  vec4 wall=beauty(uv-lift*.30);
  vec4 foot=beauty(uv);
  vec2 castOffset=unit*(vec2(.46,.82)-lean*.21);
  float contact=beauty(uv-castOffset).a;
  float penumbra=beauty(uv-castOffset*1.9-unit*.08).a;
  float shade=.39*contact+.19*penumbra;
  if(cap.a+wall.a+foot.a+shade<.003)return vec4(0.);
  vec4 material=texture(surfaceMap,topUV);
  vec2 slope=material.rg*2.-1.;
  vec3 n=normalize(vec3(slope,sqrt(max(.045,1.-dot(slope,slope)))));
  vec3 eye=normalize(vec3(-.81*pose.x,-.67*pose.y,1.));
  float faceted=1.-step(.5,abs(pose.z-1.));
  float inlaid=step(1.5,pose.z);
  float gold=inlaid*(1.-smoothstep(.64,.82,material.b));
  float thick=clamp((material.b*255.-216.)/36.,0.,1.);
  float facing=max(0.,dot(n,eye));
  float rim=(1.-facing)*(1.-facing)-(1.-n.z)*(1.-n.z);
  float change=reflection(n,eye,faceted)-reflection(n,vec3(0.,0.,1.),faceted);
  float backlight=smoothstep(-.4,.82,dot(n,normalize(vec3(.68+.36*eye.x,-.56+.30*eye.y,.25))));
  vec4 core=beauty(topUV+unit*lean*(.18+.56*thick));
  vec3 body=mix(cap.rgb,core.rgb,core.a*.28*(1.-gold));
  vec3 transmitted=mix(body,vec3(.73,.93,.79),.36-.11*inlaid);
  body=mix(body,transmitted,min(1.,length(lean))*backlight*(1.-thick*.86)*(.39-.15*inlaid));
  vec3 polished=body*(1.+.40*min(change,0.))
               +vec3(.96,.99,.90)*(max(change,0.)+.07*rim)*material.a;
  vec3 wire=cap.rgb*(1.+.62*min(change,0.))+vec3(1.,.83,.48)*(1.37*max(change,0.)+.11*rim);
  vec3 front=mix(polished,wire,gold);
  float opacity=shade;
  vec3 premul=vec3(.025,.043,.037)*shade;
  vec3 basal=mix(foot.rgb*.40,vec3(.035,.10,.081),.28);
  premul=mix(premul,basal,foot.a);
  opacity+=foot.a*(1.-opacity);
  premul=mix(premul,wall.rgb*(.51+.11*facing),wall.a);
  opacity+=wall.a*(1.-opacity);
  premul=mix(premul,front,cap.a);
  opacity+=cap.a*(1.-opacity);
  return vec4(premul/max(.0001,opacity),opacity)*tint;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

